/**
 * Edge TTS — the token that must never expire, and the protocol that uses it.
 *
 * The three values pinned below were generated by the AUTHORITATIVE
 * implementation of the Sec-MS-GEC v2 token. If Microsoft changes the
 * algorithm (as they did between v1 and v2 — v1 was a plain SHA-256), this
 * test fails FIRST, here, and not as a mysterious 403 in a user's hand.
 * Update the port, keep the tests honest.
 */
import { describe, expect, it } from 'vitest'
import {
  SEC_MS_GEC_VERSION,
  edgeSpeak,
  WIN_EPOCH,
  buildSeedWords,
  buildSsml,
  buildConfigMessage,
  buildSsmlMessage,
  edgeWssUrl,
  generateSecMsGec,
  generateSecMsGecV2,
  jsTimestamp,
  listEdgeVoices,
  sanitizeText,
  sha256Digest,
  sha256Init,
  splitHeadersAndData,
  voicesHeaders,
  wssHeaders,
} from '../src/edgeTts'
import { WssFrameParser, buildHandshakeRequest, encodeClientFrame } from '../src/edgeTts/wss'

const PINNED: Array<[number, string]> = [
  [
    1763970000.0,
    'D5957851F41F9A50-D4A68EB2D13AAB21A54B4BA822AD5A9559AD646D38365026213F41C477EB0F04',
  ],
  [
    1763970600.5,
    'D2746D4B4A719C34-AB6ECE8434909AD668042C01C2A1710555768C141AEB14180A0A411D31726CB3',
  ],
  [
    1764000123.75,
    'BB2B3ADE6A8DD1F3-B07567543B86F99C3539F563D8D3368C59A22CAF50BF1E35F42DA34792F80A76',
  ],
]

describe('Sec-MS-GEC v2 token', () => {
  it('reproduces the authoritative values bit for bit', () => {
    for (const [timestamp, expected] of PINNED) {
      expect(generateSecMsGecV2(timestamp)).toBe(expected)
    }
  })

  it('has the <16 hex>-<64 hex> shape', () => {
    const token = generateSecMsGecV2(1763970000)
    expect(token).toMatch(/^[0-9A-F]{16}-[0-9A-F]{64}$/)
  })

  it('is derived from the CLOCK — nothing here can expire', () => {
    // Same window → same token; the next 5-minute window → a DIFFERENT one.
    expect(generateSecMsGecV2(1763970000)).toBe(generateSecMsGecV2(1763970100))
    expect(generateSecMsGecV2(1763970000)).not.toBe(generateSecMsGecV2(1763970300))
  })

  it('publishes the Edge version the endpoint pins', () => {
    expect(SEC_MS_GEC_VERSION).toMatch(/^2-\d+\.\d+\.\d+\.\d+$/)
  })

  it('pins the modified-IV seed words (the port is exact)', () => {
    const data = new TextEncoder().encode('1340844360000000006A5AA1D4EAFF4E9FB37E23D68491D6F4')
    const words = buildSeedWords(data.subarray(0, 7)).map((w) => w.toString(16).padStart(8, '0'))
    expect(words[14]!).toBe('00313334')
    expect(words[15]!).toBe('30383434')
    expect(words[16]!).toBe('ab1bde30')
    expect(sha256Init(data.subarray(0, 7)).map((w) => w.toString(16).padStart(8, '0'))[0]).toBe('7b67619e')
    expect(
      Array.from(sha256Digest(data), (b) => b.toString(16).padStart(2, '0'))
        .join('')
        .toUpperCase(),
    ).toBe('D4A68EB2D13AAB21A54B4BA822AD5A9559AD646D38365026213F41C477EB0F04')
  })

  it('survives a missing date header without throwing', () => {
    expect(generateSecMsGec()).toMatch(/^[0-9A-F]{16}-[0-9A-F]{64}$/)
  })

  it('exposes the epoch constant the ticks are built from', () => {
    expect(WIN_EPOCH).toBe(11644473600)
  })
})

describe('voice list request', () => {
  it('sends the clock token and the pinned version', () => {
    const headers = voicesHeaders()
    expect(headers['Sec-MS-GEC']).toMatch(/^[0-9A-F]{16}-[0-9A-F]{64}$/)
    expect(headers['Sec-MS-GEC-Version']).toBe(SEC_MS_GEC_VERSION)
    expect(headers['User-Agent']).toContain('Edg/143')
  })

  it('does NOT put the socket-only Origin on the fetch', () => {
    // A chrome-extension Origin makes the fetch layer refuse the connection
    // itself (measured) — the voice list must not carry it.
    expect(voicesHeaders().Origin).toBeUndefined()
    expect(wssHeaders().Origin).toBe('chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold')
  })

  it('parses the catalog into storable voice ids', async () => {
    const voices = await listEdgeVoices(async () =>
      new Response(JSON.stringify([{ ShortName: 'pt-BR-AntonioNeural', Gender: 'Male', Locale: 'pt-BR' }])),
    )
    expect(voices).toHaveLength(1)
    expect(voices[0]?.shortName).toBe('pt-BR-AntonioNeural')
    expect(voices[0]?.locale).toBe('pt-BR')
  })

  it('turns a 403 into a retryable, honest error', async () => {
    await expect(
      listEdgeVoices(async () => new Response('', { status: 403, headers: { Date: 'Tue, 24 Nov 2026 09:00:00 GMT' } })),
    ).rejects.toThrow(/403/)
  })
})

describe('protocol messages', () => {
  it('writes the SSML with the synthesis namespace and the locale', () => {
    const ssml = buildSsml({ text: 'Olá', voice: 'pt-BR-AntonioNeural' })
    expect(ssml).toContain("xmlns='http://www.w3.org/2001/10/synthesis'")
    expect(ssml).toContain("xml:lang='pt-BR'")
    expect(ssml).toContain("<voice name='pt-BR-AntonioNeural'>")
  })

  it('escapes the spoken text (voice names and text are different trust levels)', () => {
    expect(buildSsml({ text: '<script>&"\'', voice: 'v' })).toContain('<script>&"&apos;')
  })

  it('removes exactly the control characters the service rejects', () => {
    // The reference's rejected ranges: 0-8, 11-12, 14-31. TAB (9) and LF
    // (10) are legal on the wire and must SURVIVE.
    expect(sanitizeText('a\u0000b\u000bc\td\ne')).toBe('a b c\td\ne')
  })

  it('pins the speech.config header ORDER and trailing CRLF', () => {
    const message = buildConfigMessage(new Date(0))
    expect(message.startsWith('X-Timestamp:')).toBe(true)
    expect(message).toContain('Content-Type:application/json; charset=utf-8\r\nPath:speech.config\r\n\r\n')
    expect(message.endsWith('\r\n')).toBe(true)
    expect(message).toContain('"outputFormat":"audio-24khz-48kbitrate-mono-mp3"')
  })

  it('pins the X-Timestamp "Z" the protocol reproduces (an Edge bug)', () => {
    const message = buildSsmlMessage({ text: 'x', voice: 'v' }, 'req', new Date(0))
    expect(message).toContain(`X-Timestamp:${jsTimestamp(new Date(0))}Z\r\n`)
    expect(message).toContain('Path:ssml\r\n\r\n')
  })

  it('puts the clock token in the socket URL, ConnectionId first', () => {
    const url = edgeWssUrl('abc123')
    expect(url.startsWith('wss://speech.platform.bing.com/consumer/speech/synthesize/readaloud/edge/v1?')).toBe(true)
    expect(url).toContain(`TrustedClientToken=`)
    expect(url).toContain('ConnectionId=abc123')
    expect(url).toContain(`Sec-MS-GEC-Version=${SEC_MS_GEC_VERSION}`)
    expect(url).toMatch(/Sec-MS-GEC=[0-9A-F]{16}-[0-9A-F]{64}/)
  })
})

describe('WebSocket codec', () => {
  it('masks client frames and sets FIN + opcode', () => {
    const frame = encodeClientFrame(Buffer.from('hi'), 1)
    expect(frame[0]).toBe(0x81)
    expect(frame[1]! & 0x80).toBe(0x80) // MASK bit
    expect(frame[1]! & 0x7f).toBe(2) // payload length
    expect(frame.length).toBe(2 + 4 + 2)
  })

  it('uses the 16-bit extended length past 125 bytes', () => {
    const frame = encodeClientFrame(Buffer.alloc(200), 2)
    expect(frame[1]! & 0x7f).toBe(126)
    expect(frame.readUInt16BE(2)).toBe(200)
  })

  it('parses server frames split across chunks (never misparses partial data)', () => {
    const parser = new WssFrameParser()
    const payload = Buffer.from('perfectly fine payload')
    // A server frame is NEVER masked: [opcode][len][payload].
    const serverFrame = Buffer.concat([Buffer.from([0x81, payload.length]), payload])
    expect(parser.push(serverFrame.subarray(0, 8))).toHaveLength(0)
    const frames = parser.push(serverFrame.subarray(8))
    expect(frames).toHaveLength(1)
    expect(frames[0]?.payload.toString()).toBe('perfectly fine payload')
  })

  it('parses a 16-bit-extended server frame', () => {
    const parser = new WssFrameParser()
    const payload = Buffer.alloc(500, 7)
    const header = Buffer.alloc(4)
    header[0] = 0x82
    header[1] = 126
    header.writeUInt16BE(500, 2)
    const frames = parser.push(Buffer.concat([header, payload]))
    expect(frames).toHaveLength(1)
    expect(frames[0]?.payload).toHaveLength(500)
  })

  it('splits the Edge binary framing: length prefix + Path:audio', () => {
    const headerText = 'X-RequestId:abc\r\nContent-Type:audio/mpeg\r\nPath:audio\r\n'
    const audio = Buffer.from([0xff, 0xfb, 0x90, 0x00])
    const payload = Buffer.concat([
      (() => {
        const b = Buffer.alloc(2)
        b.writeUInt16BE(headerText.length, 0)
        return b
      })(),
      Buffer.from(headerText, 'utf8'),
      Buffer.from('\r\n', 'utf8'),
      audio,
    ])
    const headerLength = payload.readUInt16BE(0)
    const headers = new Map<string, string>()
    for (const line of payload.subarray(2, 2 + headerLength).toString('utf8').split('\r\n')) {
      const colon = line.indexOf(':')
      if (colon > 0) headers.set(line.slice(0, colon).trim().toLowerCase(), line.slice(colon + 1).trim())
    }
    const data = payload.subarray(2 + headerLength + 2)
    expect(headers.get('path')).toBe('audio')
    expect(headers.get('content-type')).toBe('audio/mpeg')
    expect(data.equals(audio)).toBe(true)
  })

  it('splits text frames on the blank line', () => {
    const { headers, data } = splitHeadersAndData(Buffer.from('Path:turn.end\r\n\r\n{}'))
    expect(headers.get('path')).toBe('turn.end')
    expect(data.toString()).toBe('{}')
  })

  it('builds an upgrade request with the endpoint path', () => {
    const request = buildHandshakeRequest('wss://speech.platform.bing.com/consumer/x?TrustedClientToken=t', {
      Origin: 'chrome-extension://x',
    })
    expect(request).toContain('GET /consumer/x?TrustedClientToken=t HTTP/1.1')
    expect(request).toContain('Host: speech.platform.bing.com')
    expect(request).toContain('Sec-WebSocket-Version: 13')
    expect(request).toContain('Origin: chrome-extension://x')
    expect(request.endsWith('\r\n\r\n')).toBe(true)
  })
})

describe('edgeSpeak resilience', () => {
  /**
   * A fake socket that replays scripted chunks/failures. Events are BUFFERED
   * until a listener exists — the provider attaches its handlers right after
   * the socket resolves, and emitting before that would lose the frames.
   */
  function fakeSocket(script: Array<{ data?: Buffer; error?: Error; close?: boolean; end?: boolean }>) {
    const handlers = new Map<string, Array<(arg: unknown) => void>>()
    const buffered: Array<[string, unknown]> = []
    const emit = (event: string, arg?: unknown) => {
      const listeners = handlers.get(event) ?? []
      if (listeners.length === 0) {
        buffered.push([event, arg])
        return
      }
      for (const h of listeners) h(arg)
    }
    const replay = () => {
      for (const [event, arg] of buffered.splice(0)) {
        for (const h of handlers.get(event) ?? []) h(arg)
      }
    }
    setImmediate(() => {
      for (const step of script) {
        if (step.data) emit('data', step.data)
        else if (step.error) emit('error', step.error)
        else if (step.close) emit('close')
        else if (step.end) emit('end')
      }
      replay()
    })
    return {
      written: [] as Buffer[],
      on(event: string, listener: (arg: unknown) => void) {
        const list = handlers.get(event) ?? []
        list.push(listener)
        handlers.set(event, list)
      },
      write: () => undefined,
      end: () => undefined,
      destroy: () => undefined,
    }
  }

  /** A binary audio frame + `Path:turn.end` text frame. */
  function turnFrames(audioBytes = 4000) {
    const headerText = 'X-RequestId:abc\r\nContent-Type:audio/mpeg\r\nPath:audio\r\n'
    const audio = Buffer.alloc(audioBytes, 7)
    const bin = Buffer.concat([
      (() => { const b = Buffer.alloc(2); b.writeUInt16BE(headerText.length, 0); return b })(),
      Buffer.from(headerText, 'utf8'),
      Buffer.from('\r\n', 'utf8'),
      audio,
    ])
    const text = Buffer.from('Path:turn.end\r\n\r\n{}')
    const frame = (payload: Buffer, opcode: number) => {
      if (payload.length < 126) {
        const h = Buffer.alloc(2)
        h[0] = 0x80 | opcode
        h[1] = payload.length
        return Buffer.concat([h, payload])
      }
      // 126: 16-bit extended length (the audio frame is several KB).
      const h = Buffer.alloc(4)
      h[0] = 0x80 | opcode
      h[1] = 126
      h.writeUInt16BE(payload.length, 2)
      return Buffer.concat([h, payload])
    }
    return [frame(bin, 2), frame(text, 1)]
  }

  it('succeeds on the first attempt', async () => {
    const chunks = turnFrames()
    const result = await edgeSpeak({
      text: 'olá',
      voice: 'pt-BR-AntonioNeural',
      connectSocket: async () => fakeSocket([{ data: chunks[0] }, { data: chunks[1] }]) as never,
    })
    expect(result.bytes.byteLength).toBeGreaterThan(1000)
  })

  it('RETRIES a transient socket error on a fresh connection', async () => {
    const chunks = turnFrames()
    let calls = 0
    const result = await edgeSpeak({
      text: 'olá',
      voice: 'pt-BR-AntonioNeural',
      connectSocket: async () => {
        calls += 1
        if (calls === 1) {
          // the first attempt dies mid-network, like a real ECONNRESET
          return fakeSocket([{ error: new Error('read ECONNRESET') }]) as never
        }
        return fakeSocket([{ data: chunks[0] }, { data: chunks[1] }]) as never
      },
    })
    expect(calls).toBe(2)
    expect(result.bytes.byteLength).toBeGreaterThan(1000)
  })

  it('gives up honestly after the attempts (no silent fake voice)', async () => {
    await expect(
      edgeSpeak({
        text: 'olá',
        voice: 'pt-BR-AntonioNeural',
        connectSocket: async () => fakeSocket([{ error: new Error('read ECONNRESET') }]) as never,
      }),
    ).rejects.toThrow(/ECONNRESET/)
  })

  it('does not retry a validation error (that is not transient)', async () => {
    let calls = 0
    await expect(
      edgeSpeak({
        text: '',
        voice: 'pt-BR-AntonioNeural',
        connectSocket: async () => {
          calls += 1
          return fakeSocket([]) as never
        },
      }),
    ).rejects.toThrow(/nothing to speak/)
    expect(calls).toBe(0)
  })
})

describe('timestamp helper', () => {
  it('writes the JavaScript-style UTC date the endpoint expects', () => {
    expect(jsTimestamp(new Date(Date.UTC(2026, 10, 24, 9, 5, 1)))).toBe(
      'Tue Nov 24 2026 09:05:01 GMT+0000 (Coordinated Universal Time)',
    )
  })
})